<form action="/newsletter/subscribe" method="POST" class="flex gap-2">
    <input type="email" name="email" placeholder="Your Email Address" required class="flex-grow bg-slate-800 text-white placeholder-slate-500 text-xs rounded-button border border-slate-700 px-3 py-2 focus:outline-none focus:border-primary">
    <button type="submit" class="bg-primary hover:bg-primary-600 text-white font-bold text-xs px-4 py-2 rounded-button transition-colors">Join</button>
</form>